import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference — Glacier Pack","description":"Every setting on every Glacier Pack addon pane — name, type, default, what it does, when to change it, and common mistakes — grouped per addon.","frontmatter":{"title":"Configuration Reference — Glacier Pack","description":"Every setting on every Glacier Pack addon pane — name, type, default, what it does, when to change it, and common mistakes — grouped per addon.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/configuration/reference.md","filePath":"glacier-pack/configuration/reference.md","lastUpdated":1785522036000}'),a={name:"glacier-pack/configuration/reference.md"};function n(c,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Every setting that actually exists on the 24 Glacier Pack addon panes, grouped per addon with an anchor each. Settings marked <strong>(env-only)</strong> live in the addon&#39;s config file and are tuned via <code>.env</code>, not the hub. Addons that manage <em>records</em> instead of settings (rules, destinations, alerts) list those fields under <strong>Managed data</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All saves go through the hub&#39;s <code>_hub</code> round-trip: you always land back on the same pane, with validation errors shown above the form when a value is rejected.</p></div><hr><h2 id="basic-pack" tabindex="-1">Basic pack <a class="header-anchor" href="#basic-pack" aria-label="Permalink to &quot;Basic pack&quot;">​</a></h2><h3 id="config-editor" tabindex="-1">Config Editor <a class="header-anchor" href="#config-editor" aria-label="Permalink to &quot;Config Editor {#config-editor}&quot;">​</a></h3><p>No settings form — this pane edits the panel&#39;s live <code>.env</code> directly. Sub-tabs: <strong>Editor</strong> (structured, grouped by prefix) and <strong>Raw file</strong> (whole-file textarea).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>env[&lt;KEY&gt;]</code> (per parsed key)</td><td>text / password / true-false select</td><td>current <code>.env</code> value</td><td>One input per env key. Secret-looking keys (<code>PASSWORD</code>, <code>SECRET</code>, <code>KEY</code>, <code>TOKEN</code>, <code>SALT</code>) are masked with a reveal toggle; boolean keys get dropdowns.</td></tr><tr><td><code>env[APP_KEY]</code></td><td>password</td><td>always blank</td><td>Write-only. Blank keeps the current key; pasting a new one rotates it (format-validated as Laravel <code>base64:</code> or 32-char).</td></tr><tr><td><code>contents</code> (Raw tab)</td><td>textarea</td><td>entire file verbatim</td><td>Bulk raw edit with the same validation, backup and atomic-write flow.</td></tr><tr><td><code>backups_keep</code> <strong>(env-only)</strong></td><td>number</td><td><code>10</code></td><td>Timestamped <code>.env</code> snapshots kept in <code>storage/app/config-editor/backups</code>.</td></tr></tbody></table><p><strong>Common mistakes</strong></p><ul><li><strong>Editing <code>APP_KEY</code>.</strong> Never. Panel data encrypted with it (node database passwords) becomes unreadable.</li><li><strong>Changing <code>APP_NAME</code>, <code>SESSION_*</code>, <code>CACHE_PREFIX</code> or <code>REDIS_*</code> casually</strong> — it invalidates every active session panel-wide, logging everyone out immediately.</li><li>Forgetting that backups contain full <code>.env</code> secrets — they are written <code>0640</code> in a <code>0750</code> directory; treat them like the <code>.env</code> itself.</li></ul><hr><h3 id="console-log-share" tabindex="-1">Console Log Share <a class="header-anchor" href="#console-log-share" aria-label="Permalink to &quot;Console Log Share {#console-log-share}&quot;">​</a></h3><p>Single settings pane (no sub-tabs). Posts to <code>admin.console-log-share.update</code>; <strong>Reset to Defaults</strong> restores the shipped values.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>paste_endpoint</code></td><td>url</td><td><code>https://api.mclo.gs/1/log</code></td><td>Any mclogs-compatible API: the panel POSTs the log as form field <code>content</code> and expects JSON containing <code>url</code>. Change when self-hosting a paste service.</td></tr><tr><td><code>upload_enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the Share button and rejects uploads; <strong>Copy Log stays available</strong>.</td></tr><tr><td><code>placement</code></td><td>select</td><td><code>top</code> (Above the console)</td><td>Where the Copy/Share bar renders on the console page.</td></tr><tr><td><code>default_paste_endpoint</code> <strong>(env-only)</strong></td><td>—</td><td><code>CONSOLE_LOG_SHARE_PASTE_ENDPOINT</code>, same URL</td><td>Shipped default the reset button returns to.</td></tr><tr><td><code>max_log_lines</code> <strong>(env-only)</strong></td><td>number</td><td><code>1500</code> (<code>CONSOLE_LOG_SHARE_MAX_LINES</code>)</td><td>Trailing console lines requested from the node.</td></tr><tr><td><code>max_upload_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>5242880</code> (<code>CONSOLE_LOG_SHARE_MAX_BYTES</code>)</td><td>Largest payload pushed to the paste service; older lines are trimmed beyond it.</td></tr></tbody></table><p><strong>Common mistakes:</strong> pointing <code>paste_endpoint</code> at a plain HTML pastebin (it must be the mclogs-compatible <em>API</em> URL); changing env overrides without <code>php artisan config:clear</code>.</p><hr><h3 id="login-activity" tabindex="-1">Login Activity <a class="header-anchor" href="#login-activity" aria-label="Permalink to &quot;Login Activity {#login-activity}&quot;">​</a></h3><p>No settings — the pane is a read-only, filterable record (user / date-range filters, pagination). Deleted users show as &quot;Deleted user #id&quot;.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>admin_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code> (<code>LOGIN_ACTIVITY_ADMIN_PER_PAGE</code>)</td><td>Rows per page on the admin overview (clamped 1–100).</td></tr><tr><td><code>client_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>8</code> (<code>LOGIN_ACTIVITY_CLIENT_PER_PAGE</code>)</td><td>Rows per page in the account-area widget.</td></tr></tbody></table><p><strong>Common mistakes:</strong> none — there is nothing to misconfigure. History is kept on uninstall unless you pass <code>--drop-table</code> to <code>remove.sh</code>.</p><hr><h3 id="move-files" tabindex="-1">Move Files <a class="header-anchor" href="#move-files" aria-label="Permalink to &quot;Move Files {#move-files}&quot;">​</a></h3><p>No settings at all — the pane is an informational card. The addon enhances every server&#39;s file manager automatically once installed; there is no config file and no backend.</p><p><strong>Common mistakes:</strong> forgetting a hard refresh (<code>Ctrl+Shift+R</code>) on the Files page after install, and forgetting to re-run <code>install.sh</code> after panel updates overwrite <code>templates/base/core.blade.php</code>.</p><hr><h3 id="node-status" tabindex="-1">Node Status <a class="header-anchor" href="#node-status" aria-label="Permalink to &quot;Node Status {#node-status}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (settings + per-node overrides) and <strong>Service Updates</strong> (posts). Settings save to <code>admin.uptime.settings</code>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Master switch — off hides the Uptime tab and stops collection.</td></tr><tr><td><code>poll_interval</code></td><td>select</td><td><code>60</code> s (30 / 60 / 120 / 300)</td><td>How often the panel polls Wings. Lower = fresher graphs, more node load.</td></tr><tr><td><code>retention_days</code></td><td>select</td><td><code>90</code> (30–365)</td><td>Nightly pruning horizon; the graph window maxes at 365 days.</td></tr><tr><td><code>users_see_node_uptime</code></td><td>checkbox</td><td>on</td><td>Whether regular users see node health data.</td></tr><tr><td><code>show_node_names</code></td><td>checkbox</td><td>off</td><td>Off masks real node names/FQDNs for users (&quot;Your Node&quot;, &quot;Node 1&quot;); admins always see real names.</td></tr><tr><td><code>job_timeout</code> / <code>node_connect_timeout</code> / <code>cache_ttl</code> <strong>(env-only)</strong></td><td>numbers</td><td><code>45</code> / <code>3</code> / <code>300</code></td><td>Collection job timeout, per-node connect timeout, cache TTL (seconds).</td></tr></tbody></table><p><strong>Managed data:</strong> per-node tracking overrides (toggle per node), and Service Update posts with <code>title</code> (required), <code>event_at</code> (optional — renders a live countdown) and <code>body_html</code> (required; whitelisted basic HTML).</p><p><strong>Common mistakes:</strong> missing the panel cron — collection (<code>uptime:collect</code>) and pruning run via the scheduler; forgetting the <code>uptime.read</code> subuser permission, without which users see no Uptime tab.</p><hr><h3 id="panel-logs" tabindex="-1">Panel Logs <a class="header-anchor" href="#panel-logs" aria-label="Permalink to &quot;Panel Logs {#panel-logs}&quot;">​</a></h3><p>No settings form — a tool pane with a file list and a tail viewer (level filters, 2/5/10/30 s auto-refresh, download, clear, delete).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>PANEL_LOGS_TAIL_LINES</code> <strong>(env-only)</strong></td><td>number</td><td><code>400</code></td><td>Lines of context loaded when a log opens.</td></tr><tr><td><code>PANEL_LOGS_SCAN_BYTES</code> <strong>(env-only)</strong></td><td>number</td><td><code>4194304</code> (4 MiB)</td><td>Backwards scan budget for the initial tail.</td></tr><tr><td><code>PANEL_LOGS_POLL_MAX_BYTES</code> <strong>(env-only)</strong></td><td>number</td><td><code>524288</code> (512 KiB)</td><td>Max bytes per poll response.</td></tr><tr><td><code>PANEL_LOGS_POLL_INTERVAL</code> <strong>(env-only)</strong></td><td>number</td><td><code>5</code> (seconds)</td><td>Default auto-refresh interval in the viewer.</td></tr></tbody></table><p><strong>Common mistakes:</strong> none — the panel recreates a cleared or deleted log file automatically on the next write.</p><hr><h3 id="recycle-bin" tabindex="-1">Recycle Bin <a class="header-anchor" href="#recycle-bin" aria-label="Permalink to &quot;Recycle Bin {#recycle-bin}&quot;">​</a></h3><p>Single pane: global settings, storage overview, top-servers table and per-egg overrides.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off makes deletes permanent again (stock behavior).</td></tr><tr><td><code>retention_hours</code></td><td>number (1–8760)</td><td><code>24</code></td><td>Hours a trashed file stays recoverable before purge.</td></tr><tr><td><code>default_max_mb_per_server</code></td><td>number (0–10485760)</td><td><code>0</code> (unlimited)</td><td>Per-server trash capacity in MB, counted against the server&#39;s real disk. Set this on shared nodes. Files too large for the bin can only be deleted permanently.</td></tr><tr><td><code>max_files_per_delete</code></td><td>number (1–10000)</td><td><code>100</code></td><td>Cap per delete request.</td></tr><tr><td><code>purge_batch_size</code></td><td>number (50–5000)</td><td><code>200</code></td><td>Rows per chunk processed by the hourly purge job.</td></tr><tr><td><code>logging_enabled</code></td><td>checkbox</td><td>on</td><td>Write activity-log entries for trash / restore / purge.</td></tr><tr><td><code>protect_trash_dir</code></td><td>checkbox</td><td>on</td><td>Protects <code>.trash</code> from manual moves and deletion.</td></tr></tbody></table><p><strong>Managed data:</strong> per-egg overrides — <code>egg_id</code> (required), <code>retention_hours</code> (blank inherits global), <code>max_mb</code> (blank inherits global).</p><p><strong>Common mistakes:</strong> leaving capacity unlimited on busy nodes (trash eats real disk); forgetting <code>yarn build:production</code> after install <strong>and</strong> after uninstall; not re-running <code>install.sh</code> after panel updates overwrite the patched core files.</p><hr><h3 id="resource-alerts" tabindex="-1">Resource Alerts <a class="header-anchor" href="#resource-alerts" aria-label="Permalink to &quot;Resource Alerts {#resource-alerts}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Rules</strong>, <strong>History</strong>, <strong>Settings</strong>. Settings save to <code>admin.resource-alerts.settings.update</code>; <strong>Send Test Alert</strong> emails all admins and hits the configured webhooks.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>monitoring_enabled</code></td><td>checkbox</td><td>on</td><td>Pause switch — off skips every poll and fires nothing.</td></tr><tr><td><code>discord_webhook_url</code></td><td>url</td><td>empty</td><td>Discord incoming webhook for alert delivery.</td></tr><tr><td><code>slack_webhook_url</code></td><td>url</td><td>empty</td><td>Slack incoming webhook.</td></tr><tr><td><code>retention_days</code></td><td>number (1–365)</td><td><code>30</code></td><td>History records older than this are pruned daily.</td></tr><tr><td><code>history_per_page</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code></td><td>History pagination size.</td></tr></tbody></table><p><strong>Managed data (rules):</strong> <code>name</code> (max 64), <code>metric</code> (<code>cpu</code>, <code>memory</code>, <code>disk</code>, <code>network_rx</code>, <code>network_tx</code>), <code>operator</code> (<code>above</code>/<code>below</code>), <code>threshold</code> (default <code>90</code>; % for cpu/memory/disk, Mbps for network), <code>scope</code> (<code>global</code>/<code>node</code>/<code>server</code>), <code>node_id</code>/<code>server_id</code> (per scope), <code>duration_minutes</code> (1–60, default <code>1</code> — consecutive 1-minute samples outside the threshold before firing), <code>enabled</code>, <code>notify_mail</code>, <code>notify_webhook</code>. Layering: global rule → per-node override → per-server override; most specific wins.</p><p><strong>Common mistakes:</strong> enabling <code>notify_webhook</code> on rules before saving webhook URLs; treating CPU/memory/disk thresholds as absolute values (they are percentages of the server&#39;s limits); missing the panel cron — sampling runs once per minute via the scheduler.</p><hr><h3 id="url-download" tabindex="-1">URL Download <a class="header-anchor" href="#url-download" aria-label="Permalink to &quot;URL Download {#url-download}&quot;">​</a></h3><p>Single settings pane (one form, four boxes). <strong>Reset to defaults</strong> and <strong>Clear caches</strong> (remembered URLs + activity) are separate actions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>max_file_size_value</code> + <code>max_file_size_unit</code></td><td>number + select (MB/GB)</td><td><code>10</code> <code>GB</code></td><td>Files larger than this are rejected before download. <code>0</code> = unlimited.</td></tr><tr><td><code>allowed_url_schemes</code></td><td>text</td><td><code>http,https</code></td><td>Comma-separated scheme allow-list.</td></tr><tr><td><code>allowed_file_extensions</code></td><td>text</td><td>empty (all allowed)</td><td>Comma-separated without dots, e.g. <code>zip,gz,tar,jar</code>.</td></tr><tr><td><code>max_urls_allowed</code></td><td>number (1–100)</td><td><code>3</code></td><td>URLs per batch.</td></tr><tr><td><code>max_concurrent_downloads</code></td><td>number (1–50)</td><td><code>3</code></td><td>Queued + active downloads per user per server.</td></tr><tr><td><code>max_query</code> / <code>max_query_window</code></td><td>numbers</td><td><code>10</code> / <code>60</code></td><td>URL-validation rate limit (queries per window, seconds).</td></tr><tr><td><code>button_label</code></td><td>text (max 60)</td><td><code>Download from URL</code></td><td>File-manager toolbar button label.</td></tr><tr><td><code>show_progress</code></td><td>select</td><td><code>popup</code></td><td><code>popup</code>, <code>deck</code> (modal + floating deck), <code>deck_only</code>, <code>none</code>. The deck survives page reloads.</td></tr><tr><td><code>memory_limit</code></td><td>number (1–20)</td><td><code>20</code></td><td>Remembered URL chips per user.</td></tr><tr><td><code>allow_simultaneous_downloads</code></td><td>checkbox</td><td>on</td><td>Let users run a batch simultaneously instead of queued.</td></tr><tr><td><code>prevent_incomplete_downloads</code></td><td>checkbox</td><td>on</td><td>Post-transfer verification; empty/missing results are flagged and cleaned up.</td></tr><tr><td><code>follow_redirects</code></td><td>checkbox</td><td>on</td><td>Follow HTTP redirects when probing/downloading.</td></tr><tr><td><code>allow_unknown_size</code></td><td>checkbox</td><td>off</td><td>Accept downloads whose size the HEAD probe cannot determine — size limits cannot be enforced for these.</td></tr><tr><td><code>validate_urls_on_entry</code></td><td>checkbox</td><td>on</td><td>Validate URLs as the user types.</td></tr><tr><td><code>prevent_html_downloads</code></td><td>checkbox</td><td>off</td><td>Reject URLs that resolve to HTML pages.</td></tr><tr><td><code>max_active_history</code> / <code>max_failed_history</code> / <code>max_completed_history</code></td><td>numbers (0–1000)</td><td><code>20</code> each</td><td>History rows kept per state; <code>0</code> = unlimited.</td></tr><tr><td><code>stale_download_timeout</code></td><td>number (60–86400)</td><td><code>3600</code> s</td><td>A download with no progress this long is marked failed.</td></tr><tr><td><code>probe_timeout</code> <strong>(env-only)</strong></td><td>number</td><td><code>15</code> (<code>URL_DOWNLOAD_PROBE_TIMEOUT</code>)</td><td>Seconds per remote HEAD probe.</td></tr></tbody></table><p><strong>Common mistakes:</strong> enabling <code>allow_unknown_size</code> and expecting size limits to still apply; forgetting transfers run on the node via the native <code>files/pull</code> endpoint — a broken panel↔Wings link fails every download.</p><hr><h2 id="advanced-pack" tabindex="-1">Advanced pack <a class="header-anchor" href="#advanced-pack" aria-label="Permalink to &quot;Advanced pack&quot;">​</a></h2><h3 id="backup-pro" tabindex="-1">Backup Pro <a class="header-anchor" href="#backup-pro" aria-label="Permalink to &quot;Backup Pro {#backup-pro}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Destinations</strong>, <strong>Backup Rules</strong>, <strong>Backups</strong>, <strong>Archives</strong>, <strong>Activity</strong>, <strong>Settings</strong>.</p><p><strong>Settings tab</strong> (<code>admin.s3backuppro.settings.update</code>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>default_retention_count</code></td><td>number (0–10000)</td><td><code>0</code></td><td>Copies kept for manual offloads not attached to a rule; <code>0</code> = unlimited.</td></tr><tr><td><code>show_user_ui</code></td><td>checkbox</td><td>on</td><td>&quot;Protected by S3&quot; banner and cloud badges on the user&#39;s backup page.</td></tr><tr><td><code>download_source</code></td><td>select</td><td><code>auto</code></td><td>Default download/restore source: <code>auto</code> (local first, S3 fallback), <code>local</code>, <code>cloud</code>.</td></tr><tr><td><code>allow_user_cloud_download</code></td><td>checkbox</td><td>on</td><td>Users may download backups from S3 copies.</td></tr><tr><td><code>allow_user_cloud_restore</code></td><td>checkbox</td><td>off</td><td>Users may restore from S3 copies — overwrites server files, hence off.</td></tr><tr><td><code>auto_retention_mode</code></td><td>checkbox</td><td>off</td><td>Match S3 retention to each server&#39;s panel backup limit; ignores per-rule &quot;Keep newest N&quot;.</td></tr><tr><td><code>backup_rate_limit_count</code> / <code>backup_rate_limit_seconds</code></td><td>numbers</td><td><code>2</code> / <code>600</code></td><td>Backup creation throttle; window <code>0</code> = no throttle.</td></tr><tr><td><code>notify_webhook_url</code></td><td>text</td><td>empty</td><td>Discord-compatible webhook for notifications; blank disables.</td></tr><tr><td><code>notify_level</code></td><td>select</td><td><code>failures</code></td><td><code>none</code>, <code>failures</code> (recommended), <code>all</code>.</td></tr><tr><td><code>sync_check_interval</code></td><td>number (1–1440)</td><td><code>60</code></td><td>Minutes between sync checks.</td></tr><tr><td><code>allow_user_sync_trigger</code></td><td>checkbox</td><td>off</td><td>Makes the red &quot;pending&quot; cloud icon clickable for users.</td></tr></tbody></table><p><strong>Managed data:</strong></p><ul><li><strong>Destinations</strong> — <code>name</code>, <code>access_key_id</code>, <code>secret_access_key</code> (encrypted at rest; blank on edit keeps it), <code>provider_hint</code> (<code>custom</code>/<code>aws</code>/<code>r2</code>/<code>b2</code>/<code>wasabi</code>/<code>minio</code>/<code>datalix</code> — auto-fills defaults, does not affect functionality), <code>bucket</code>, <code>region</code> (default <code>us-east-1</code>; R2 = <code>auto</code>), <code>endpoint</code> (blank = AWS), <code>prefix</code>, <code>use_path_style</code> (on; most non-AWS providers require it), <code>is_enabled</code>. One-click connection tests, per-row or &quot;test all&quot;.</li><li><strong>Backup rules</strong> — <code>name</code>, <code>target_type</code> (<code>all</code>/<code>node</code>/<code>servers</code>), <code>node_id</code> or <code>servers[]</code>, <code>destinations[]</code>, <code>backup_mode</code> (<code>mirror</code> / <code>schedule</code> / <code>both</code> / <code>off</code>), <code>interval_minutes</code> (default <code>1440</code>), <code>retention_count</code> (default <code>5</code>, <code>0</code> = unlimited), <code>retention_days</code> (<code>0</code> = no age limit), <code>offload</code> (delete node copy after upload), <code>lock_backups</code>, <code>ignored_files</code> (one glob per line, <code>.pteroignore</code> syntax).</li></ul><p><strong>Env-only tuning (<code>config/s3backuppro.php</code>):</strong> <code>S3BACKUPPRO_QUEUE_CONNECTION</code> / <code>S3BACKUPPRO_QUEUE_NAME</code> (default <code>standard</code>), multipart threshold/part size (16 MiB), <code>completion_timeout_seconds</code> (3600), <code>stale_after_minutes</code> (180), <code>max_servers_per_run</code> (100), <code>prune_time</code> (04:00), <code>log_retention_days</code> (60).</p><p><strong>Common mistakes:</strong> uploads sitting pending with a red cloud icon — almost always a missing queue worker on the <code>standard</code> queue; wrong path-style/endpoint combo for the provider (AWS: blank endpoint, path-style <strong>off</strong>; R2/B2/Wasabi/MinIO: provider endpoint, path-style <strong>on</strong>).</p><hr><h3 id="database-manager" tabindex="-1">Database Manager <a class="header-anchor" href="#database-manager" aria-label="Permalink to &quot;Database Manager {#database-manager}&quot;">​</a></h3><p>Single settings pane plus a recent-operations log.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>max_export_mb</code></td><td>number</td><td><code>256</code></td><td>Databases estimated larger are refused before a dump starts.</td></tr><tr><td><code>max_import_mb</code></td><td>number</td><td><code>64</code></td><td>Upload cap for imports — the pane shows your live PHP <code>upload_max_filesize</code>/<code>post_max_size</code>; raise those first for large imports.</td></tr><tr><td><code>allow_export</code></td><td>checkbox</td><td>on</td><td>Users with <code>databasemanager.export</code> may download dumps.</td></tr><tr><td><code>allow_import</code></td><td>checkbox</td><td>on</td><td>Users with <code>databasemanager.import</code> may restore uploads.</td></tr><tr><td><code>allow_wipe</code></td><td>checkbox</td><td>on</td><td>Permit emptying the target schema before import.</td></tr><tr><td><code>log_activity</code></td><td>checkbox</td><td>on</td><td>Mirror each operation into the server&#39;s activity log.</td></tr><tr><td><code>mysqldump_binary</code> / <code>mysql_binary</code> / <code>work_directory</code> <strong>(env-only)</strong></td><td>—</td><td><code>mysqldump</code> / <code>mysql</code> / <code>storage/app/database-manager</code></td><td>Override via <code>DATABASE_MANAGER_MYSQLDUMP</code>, <code>DATABASE_MANAGER_MYSQL</code>, <code>DATABASE_MANAGER_WORKDIR</code>.</td></tr><tr><td><code>export_timeout</code> / <code>import_timeout</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>280</code> / <code>580</code></td><td>Process limits.</td></tr></tbody></table><p><strong>Common mistakes:</strong> setting <code>max_import_mb</code> above the PHP upload limits; missing <code>default-mysql-client</code> on the panel host (both binaries must be reachable by the web user).</p><hr><h3 id="mod-installer" tabindex="-1">Mod Installer <a class="header-anchor" href="#mod-installer" aria-label="Permalink to &quot;Mod Installer {#mod-installer}&quot;">​</a></h3><p>Single settings pane with provider status badges.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>From the CurseForge for Studios console. Modrinth needs no key; CurseForge stays hidden from users until a key is saved.</td></tr><tr><td><code>default_provider</code></td><td>select</td><td><code>modrinth</code></td><td>Preselected repository when a user opens the Mods page.</td></tr><tr><td><code>default_loader</code></td><td>select</td><td><code>fabric</code></td><td>Preselected loader filter (<code>fabric</code>/<code>forge</code>/<code>quilt</code>/<code>neoforge</code>/any); users can change it anytime.</td></tr><tr><td><code>install_directory</code> <strong>(env-only)</strong></td><td>path</td><td><code>/mods</code> (<code>MOD_INSTALLER_DIRECTORY</code>)</td><td>Server-relative install target.</td></tr><tr><td><code>http_timeout</code> / <code>version_manifest_ttl</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>15</code> / <code>86400</code></td><td>Provider request timeout; Minecraft version manifest cache TTL.</td></tr></tbody></table><p><strong>Common mistakes:</strong> assuming CurseForge works without a key; blocking outbound HTTPS to <code>api.modrinth.com</code>, <code>api.curseforge.com</code> or <code>launchermeta.mojang.com</code> (panel) and the mod CDNs (nodes).</p><hr><h3 id="modpack-installer" tabindex="-1">Modpack Installer <a class="header-anchor" href="#modpack-installer" aria-label="Permalink to &quot;Modpack Installer {#modpack-installer}&quot;">​</a></h3><p>Single settings pane with health badges (zip extension, staging writable, per-platform status), usage counters and a recent-installs table.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enable_modrinth</code></td><td>checkbox</td><td>on</td><td>Modrinth works out of the box, no key required.</td></tr><tr><td><code>enable_curseforge</code></td><td>checkbox</td><td>off</td><td>Requires an API key from the CurseForge console.</td></tr><tr><td><code>curseforge_api_key</code></td><td>text</td><td>always rendered blank</td><td>Stored key is never shown; blank keeps it.</td></tr><tr><td><code>clear_curseforge_key</code></td><td>checkbox</td><td>off</td><td>Check + save to remove the stored key.</td></tr><tr><td><code>button_label</code></td><td>text (max 40)</td><td><code>Modpacks</code></td><td>File-manager button label.</td></tr><tr><td><code>results_per_page</code></td><td>number (5–50)</td><td><code>20</code></td><td>Search results per page.</td></tr><tr><td><code>cache_ttl_minutes</code></td><td>number (5–1440)</td><td><code>30</code></td><td>Platform response cache — respects catalogue rate limits.</td></tr><tr><td><code>max_archive_size_mb</code></td><td>number (10–2048)</td><td><code>512</code></td><td>Pack archives/bundles larger than this are rejected.</td></tr><tr><td><code>max_files_per_pack</code></td><td>number (10–20000)</td><td><code>2500</code></td><td>File-count cap per pack.</td></tr><tr><td><code>max_staged_file_mb</code> / <code>max_staged_total_mb</code></td><td>numbers</td><td><code>5</code> / <code>64</code></td><td>Caps for configs and other files shipped inside the pack archive.</td></tr><tr><td><code>plan_rate_limit</code> / <code>plan_rate_window</code></td><td>numbers</td><td><code>5</code> / <code>300</code></td><td>How often one user may prepare an install per server.</td></tr><tr><td><code>allow_clean_install</code></td><td>checkbox</td><td>on</td><td>Users may wipe the target directory before pack files land.</td></tr></tbody></table><p>Separate actions: <strong>Clear platform cache</strong>, <strong>Clear staging files</strong>, <strong>Reset defaults</strong> (resets limits, keeps the API key).</p><p><strong>Common mistakes:</strong> missing the PHP <code>zip</code> extension or a non-writable <code>storage/app/modpack-installer</code> (both shown as pane badges); expecting egg/Docker changes — the addon installs files only, and client-only mods plus third-party-opt-out files are auto-skipped and listed on the confirmation screen.</p><hr><h3 id="node-stats" tabindex="-1">Node Stats <a class="header-anchor" href="#node-stats" aria-label="Permalink to &quot;Node Stats {#node-stats}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Nodes</strong>, <strong>Capacity</strong>, <strong>Historical</strong>, <strong>Top Consumers</strong>, <strong>Reports</strong>, <strong>Settings</strong>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>collection_enabled</code></td><td>yes/no radio</td><td>yes</td><td>Master switch for metric collection from Wings.</td></tr><tr><td><code>collection_interval</code></td><td>number (10–300)</td><td><code>30</code> s</td><td>How often metrics are collected.</td></tr><tr><td><code>retention_raw_days</code></td><td>number (1–365)</td><td><code>7</code></td><td>Raw snapshot retention.</td></tr><tr><td><code>retention_1m_days</code></td><td>number (1–365)</td><td><code>30</code></td><td>1-minute aggregate retention.</td></tr><tr><td><code>retention_5m_days</code></td><td>number (1–730)</td><td><code>90</code></td><td>5-minute aggregate retention.</td></tr><tr><td><code>retention_1h_days</code></td><td>number (1–1825)</td><td><code>365</code></td><td>Hourly aggregate retention.</td></tr><tr><td><code>retention_1d_days</code></td><td>number (1–3650)</td><td><code>1825</code></td><td>Daily aggregate retention.</td></tr><tr><td><code>retention.aggregates_1mo_days</code> <strong>(env-only)</strong></td><td>number</td><td><code>0</code> (keep forever)</td><td>Monthly aggregate retention.</td></tr></tbody></table><p><strong>Env-only (<code>config/nodeanalytics.php</code>):</strong> queue name <code>nodeanalytics</code>, batch sizes (collection 50 / aggregation 500), cache TTL 60 s, <code>reports.max_rows</code> 100000.</p><p><strong>Common mistakes:</strong> dashboards staying empty — the addon needs both the panel cron (the scheduler runs <code>nodeanalytics:schedule</code> every minute) <strong>and</strong> a Supervisor worker on the <code>nodeanalytics</code> queue (<code>data/install-queue-worker.sh</code> sets it up).</p><hr><h3 id="permission-manager" tabindex="-1">Permission Manager <a class="header-anchor" href="#permission-manager" aria-label="Permalink to &quot;Permission Manager {#permission-manager}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong>, <strong>Roles</strong>, <strong>Members</strong>, <strong>Audit Log</strong>. No global settings form — the panes manage roles, members and scoped assignments.</p><p><strong>Managed data:</strong></p><ul><li><strong>Roles</strong> — <code>name</code> (required), <code>description</code>, <code>pages[]</code> (which staff-area pages the role can open: Users, Servers, Nodes, Nests), <code>see_all_servers</code>, <code>see_all_users</code> (off = only explicitly assigned servers/users), <code>allow_build_edit</code> (edit CPU/memory/disk/swap/IO/feature limits via the panel&#39;s own build service), <code>subuser_permissions[]</code> (defaults to console, power actions and file read — provisioned as a <em>real</em> subuser on every in-scope server; editing re-syncs all members).</li><li><strong>Members</strong> — <code>user_id</code>, <code>role_id</code>, <code>active</code> (unchecking revokes access and provisioned subusers but keeps assignments). Per member: assign specific users (staff then see those users <em>and their servers</em>) and specific servers.</li><li><strong>Config-only (<code>config/permissionmanager.php</code>):</strong> the page list and <code>default_subuser_permissions</code> (<code>websocket.connect</code>, <code>control.console</code>, <code>control.start</code>, <code>control.stop</code>, <code>control.restart</code>, <code>file.read</code>, <code>file.read-content</code>).</li></ul><p><strong>Common mistakes:</strong> trying to delete a role that still has members (refused — reassign or remove them first); uninstalling without removing members or running <code>php artisan permgr:sync</code>, which leaves provisioned subusers behind.</p><hr><h3 id="player-list" tabindex="-1">Player List <a class="header-anchor" href="#player-list" aria-label="Permalink to &quot;Player List {#player-list}&quot;">​</a></h3><p>Single settings pane with a built-in host:port test tool.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the widget panel-wide without uninstalling.</td></tr><tr><td><code>protocol</code></td><td>select</td><td><code>auto</code></td><td><code>auto</code> (query, then ping), <code>query</code> (UDP query only), <code>ping</code> (status ping only). Query returns the full list but needs <code>enable-query=true</code>; ping needs no setup but returns only a name sample.</td></tr><tr><td><code>timeout_ms</code></td><td>number (250–10000)</td><td><code>2000</code></td><td>Per probe attempt.</td></tr><tr><td><code>cache_seconds</code></td><td>number (0–300)</td><td><code>15</code></td><td>Per-server result cache — prevents query floods.</td></tr><tr><td><code>poll_seconds</code></td><td>number (5–300)</td><td><code>20</code></td><td>Browser refresh interval of the console widget.</td></tr></tbody></table><p>All five also have env defaults (<code>PLAYER_LIST_ENABLED</code>, <code>PLAYER_LIST_PROTOCOL</code>, <code>PLAYER_LIST_TIMEOUT_MS</code>, <code>PLAYER_LIST_CACHE_SECONDS</code>, <code>PLAYER_LIST_POLL_SECONDS</code>).</p><p><strong>Common mistakes:</strong> expecting full player lists from servers without <code>enable-query=true</code> and the query port reachable from the panel — the ping fallback only ever returns a sample.</p><hr><h3 id="player-manager" tabindex="-1">Player Manager <a class="header-anchor" href="#player-manager" aria-label="Permalink to &quot;Player Manager {#player-manager}&quot;">​</a></h3><p>Single settings pane plus a stored-credentials table (passwords shown only as <code>stored</code>/<code>—</code>, never the value).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off answers the client page and every API action with a disabled notice.</td></tr><tr><td><code>default_port</code></td><td>number (1–65535)</td><td><code>25575</code></td><td>Used when neither a stored override nor a server variable defines a port (vanilla default).</td></tr><tr><td><code>connect_timeout</code></td><td>number (1.0–15.0)</td><td><code>3.0</code> s</td><td>RCON connect timeout.</td></tr><tr><td><code>read_timeout</code></td><td>number (1.0–30.0)</td><td><code>4.0</code> s</td><td>RCON response timeout.</td></tr></tbody></table><p><strong>Config-only:</strong> the server-variable names consulted when no per-server override exists — <code>RCON_PASSWORD</code>, <code>RCON_PORT</code>, <code>RCON_HOST</code> (overridable via <code>PLAYER_MANAGER_VARIABLE_PASSWORD/PORT/HOST</code>).</p><p><strong>Common mistakes:</strong> servers unreachable because RCON is not enabled in <code>server.properties</code> (<code>enable-rcon=true</code>, <code>rcon.port</code>, <code>rcon.password</code>) or the port is firewalled from the panel host; forgetting the credential resolution order — stored per-server override first, then server variables, host defaulting to the primary allocation.</p><hr><h3 id="plugin-installer" tabindex="-1">Plugin Installer <a class="header-anchor" href="#plugin-installer" aria-label="Permalink to &quot;Plugin Installer {#plugin-installer}&quot;">​</a></h3><p>Single settings pane (save only; no reset/test actions).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>provider_modrinth</code> / <code>provider_hangar</code> / <code>provider_spiget</code></td><td>checkboxes</td><td>on</td><td>Free catalogues, no API key required. Spiget lists premium resources but cannot install them.</td></tr><tr><td><code>provider_curseforge</code></td><td>checkbox</td><td>off</td><td>Stays unavailable until a valid API key is saved, even when toggled on.</td></tr><tr><td><code>provider_polymart</code></td><td>checkbox</td><td>off</td><td>Marketplace catalogue; only entries flagged downloadable are installable.</td></tr><tr><td><code>curseforge_api_key</code></td><td>text</td><td>empty</td><td>From the CurseForge console; empty keeps CurseForge disabled.</td></tr><tr><td><code>install_directory</code></td><td>text</td><td><code>/plugins</code></td><td>Server-relative install target — <code>/plugins</code> for Bukkit-based, <code>/mods</code> for modded setups. Normalized to a leading slash; falls back to <code>/plugins</code> when empty, <code>/</code>, containing <code>..</code>, or over 64 chars.</td></tr><tr><td><code>analysis_max_mb</code></td><td>number (1–100)</td><td><code>15</code></td><td>Jars larger than this are listed in the Installed tab but skipped for metadata extraction and update checks.</td></tr><tr><td><code>provider_timeout</code> <strong>(env-only)</strong></td><td>seconds</td><td><code>20</code> (<code>PLUGIN_INSTALLER_PROVIDER_TIMEOUT</code>)</td><td>Catalogue request timeout.</td></tr></tbody></table><p><strong>Common mistakes:</strong> no installs landing — nodes must reach the provider CDNs (Wings performs the download via native file-pull); strict CSP blocking provider icon hosts (icons fall back to letter placeholders).</p><hr><h3 id="server-importer" tabindex="-1">Server Importer <a class="header-anchor" href="#server-importer" aria-label="Permalink to &quot;Server Importer {#server-importer}&quot;">​</a></h3><p>Sub-tabs: <strong>Overview</strong> (connections + runs) and <strong>Run report</strong>. No persistent settings — all inputs are per-operation.</p><p><strong>Managed data:</strong></p><ul><li><strong>Connections</strong> — <code>name</code>, <code>base_url</code> (public root URL of the source panel), <code>token</code> (Application API key <code>ptla_…</code>, min 16 chars, stored encrypted, with read access to servers, users, nodes, nests and eggs), <code>verify_tls</code> (on; uncheck for self-signed panels).</li><li><strong>Runs (dry run form)</strong> — <code>connection_id</code>, <code>target_node_id</code> (allocations claimed from its free pool), <code>fallback_egg_id</code> (optional; unmatched eggs otherwise become conflicts), <code>owner_strategy</code> (<code>map</code> by email / <code>fixed</code> one account), <code>fixed_user_id</code>, <code>create_missing_users</code>, <code>include_suspended</code>, <code>skip_scripts</code>.</li><li><strong>Config-only (<code>config/server-importer.php</code>):</strong> <code>per_page</code> 50, <code>timeout</code> 15 s, <code>connect_timeout</code> 8 s, <code>max_servers_per_run</code> 500.</li></ul><p><strong>Common mistakes:</strong> skipping the dry run — it builds the full conflict report and changes nothing; executing against a node without enough free allocations (claims are re-verified between dry run and import). Rollback force-deletes every server a run created.</p><hr><h3 id="server-properties" tabindex="-1">Server Properties <a class="header-anchor" href="#server-properties" aria-label="Permalink to &quot;Server Properties {#server-properties}&quot;">​</a></h3><p>Single settings pane.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>nav_label</code></td><td>text (max 30)</td><td><code>Properties</code></td><td>Label of the tab in the server sub-navigation.</td></tr><tr><td><code>file_name</code></td><td>text (max 64)</td><td><code>server.properties</code></td><td>File in the server root the editor reads/writes. Bare file names only.</td></tr><tr><td><code>allowed_nests</code></td><td>text</td><td><code>1</code></td><td>Comma-separated nest IDs the editor is available for (<code>1</code> = stock Minecraft). Empty = every nest.</td></tr><tr><td><code>show_descriptions</code></td><td>checkbox</td><td>on</td><td>Short explanation under each known key.</td></tr><tr><td><code>max_file_bytes</code> <strong>(env-only)</strong></td><td>number</td><td><code>1048576</code> (<code>SERVERPROPERTIES_MAX_FILE_BYTES</code>)</td><td>Refuse to read files larger than this.</td></tr></tbody></table><p>All four UI settings also have env defaults (<code>SERVERPROPERTIES_NAV_LABEL</code>, <code>SERVERPROPERTIES_FILE_NAME</code>, <code>SERVERPROPERTIES_ALLOWED_NESTS</code>, <code>SERVERPROPERTIES_SHOW_DESCRIPTIONS</code>).</p><p><strong>Common mistakes:</strong> expecting instant effect — Minecraft reads <code>server.properties</code> at boot, so changes apply after a restart; pointing <code>file_name</code> at a path (only a bare name is accepted).</p><hr><h3 id="staff-requests" tabindex="-1">Staff Requests <a class="header-anchor" href="#staff-requests" aria-label="Permalink to &quot;Staff Requests {#staff-requests}&quot;">​</a></h3><p>Single pane: policy settings, stat tiles, recent requests, active grants, audit trail (the three tables are read-only; approve/deny/revoke happens on the user side).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>access_mode</code></td><td>select</td><td><code>everyone</code></td><td>Who can use Staff Requests: <code>everyone</code>, <code>allowlist</code>, <code>blacklist</code>. Root admins always bypass.</td></tr><tr><td><code>allowlist</code></td><td>textarea</td><td>empty</td><td>One email per line; only these accounts may use the feature (shown when mode = allowlist).</td></tr><tr><td><code>blacklist</code></td><td>textarea</td><td>empty</td><td>One email per line; these accounts are blocked (shown when mode = blacklist).</td></tr><tr><td><code>request_decay_hours</code></td><td>number (1–8760)</td><td><code>24</code></td><td>Unanswered requests expire after this; runs on the panel&#39;s schedule cron.</td></tr><tr><td><code>block_rate_limit</code></td><td>number (1–1000)</td><td><code>10</code></td><td>Block-user actions per user per minute.</td></tr><tr><td><code>request_ttl_days</code> <strong>(env-only)</strong></td><td>number</td><td><code>14</code> (<code>ASKACCESS_REQUEST_TTL_DAYS</code>)</td><td>Separate backend validity window for pending requests — distinct from <code>request_decay_hours</code>.</td></tr><tr><td><code>max_pending_per_user</code> <strong>(env-only)</strong></td><td>number</td><td><code>25</code> (<code>ASKACCESS_MAX_PENDING</code>)</td><td>Pending-request cap per user.</td></tr><tr><td><code>create_rate_limit</code> / <code>create_rate_window_minutes</code> <strong>(env-only)</strong></td><td>numbers</td><td><code>15</code> / <code>60</code></td><td>Request-creation rate limit.</td></tr><tr><td><code>max_servers_per_grant</code> <strong>(env-only)</strong></td><td>number</td><td><code>250</code></td><td>Cap on servers touched by a single &quot;all servers&quot; approval.</td></tr></tbody></table><p><strong>Common mistakes:</strong> confused by the two expiry knobs (<code>request_decay_hours</code> in the UI vs <code>request_ttl_days</code> in env — both exist); expecting uninstall to clean up granted access — approved requests created <strong>real subuser rows</strong> that survive uninstall.</p><hr><h3 id="subdomain-manager" tabindex="-1">Subdomain Manager <a class="header-anchor" href="#subdomain-manager" aria-label="Permalink to &quot;Subdomain Manager {#subdomain-manager}&quot;">​</a></h3><p>Sub-tabs: <strong>Settings</strong>, <strong>Domains</strong>, <strong>Records</strong>.</p><p><strong>Settings tab</strong> (<code>admin.subdomainplus.settings</code>, plus <strong>Test Cloudflare connection</strong>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>cf_token</code></td><td>password</td><td>empty</td><td>Cloudflare API token with <strong>Zone / DNS / Edit</strong>. Placeholder shows &quot;(saved - enter to change)&quot; once set.</td></tr><tr><td><code>cf_email</code> / <code>cf_api_key</code></td><td>email / password</td><td>empty</td><td>Deprecated Global API Key mode — only use when a token is impossible.</td></tr><tr><td><code>default_quota</code></td><td>number (0–100)</td><td><code>5</code></td><td>DNS records per server; <code>0</code> = unlimited.</td></tr><tr><td><code>rate_per_minute</code></td><td>number (1–120)</td><td><code>5</code></td><td>Requests per minute per server.</td></tr></tbody></table><p><strong>Managed data (domains):</strong> <code>domain</code> and <code>zone_id</code> (required), <code>allow_srv_record</code> / <code>allow_a_record</code> (both on), <code>target_ip</code> (optional forced IP; empty auto-resolves from each server&#39;s allocation FQDN), SRV presets (<code>service</code> default <code>_minecraft</code>, <code>proto</code> <code>_tcp</code>/<code>_udp</code>, <code>priority</code> 0, <code>weight</code> 5, <code>ttl</code> 1 = automatic), <code>banned_patterns</code> (PHP regex, one per line), <code>allowed_eggs[]</code> (empty = all).</p><p><strong>Common mistakes:</strong> a token without Zone / DNS / Edit scope; expecting proxied records — the addon always creates unproxied records (SRV requires it); missing the panel cron, which drives <code>subdomainplus:sync-all</code> and orphan cleanup.</p><hr><h3 id="version-changer" tabindex="-1">Version Changer <a class="header-anchor" href="#version-changer" aria-label="Permalink to &quot;Version Changer {#version-changer}&quot;">​</a></h3><p>Single settings pane plus a recent-changes table. Saving settings also flushes the manifest cache.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>What it does / when to change</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>checkbox</td><td>on</td><td>Off hides the picker in the client panel and rejects installs.</td></tr><tr><td><code>allowed_types[]</code></td><td>checkboxes</td><td><code>release</code> only</td><td>Version types users may install: <code>release</code>, <code>snapshot</code>, <code>old_beta</code>, <code>old_alpha</code>.</td></tr><tr><td><code>default_filename</code></td><td>text</td><td><code>server.jar</code></td><td>Target jar name; must match a plain <code>.jar</code> file name (validated, resets to <code>server.jar</code> otherwise).</td></tr><tr><td><code>cache_ttl</code></td><td>number (60–86400)</td><td><code>300</code></td><td>Seconds the Mojang version manifest is cached.</td></tr><tr><td><code>history_limit</code></td><td>number (0–500)</td><td><code>50</code></td><td>History entries kept per server, pruned after each install.</td></tr><tr><td><code>allow_filename_choice</code></td><td>checkbox</td><td>on</td><td>Let users override the jar name per install.</td></tr><tr><td><code>backup_previous</code></td><td>checkbox</td><td>on</td><td>Rename the current jar to <code>&lt;name&gt;.backup-&lt;timestamp&gt;</code> before writing.</td></tr><tr><td><code>update_startup_variable</code></td><td>checkbox</td><td>on</td><td>Point the egg&#39;s <code>SERVER_JARFILE</code> variable at the new jar.</td></tr><tr><td><code>manifest_url</code> / <code>http_timeout</code> / <code>http_retries</code> <strong>(env-only)</strong></td><td>—</td><td>piston-meta URL / <code>10</code> / <code>2</code></td><td>Version-service endpoint and HTTP tuning (<code>VERSION_CHANGER_MANIFEST_URL</code>, <code>VERSION_CHANGER_HTTP_TIMEOUT</code>, <code>VERSION_CHANGER_HTTP_RETRIES</code>).</td></tr></tbody></table><p><strong>Common mistakes:</strong> assuming a mirror manifest widens download sources — jar downloads are pinned to <code>mojang.com</code> / <code>minecraft.net</code> regardless; expecting the running server to switch jars live — the old jar runs until the next restart.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./../user-guide/dashboard">The Hub Dashboard →</a></strong> — how panes, sub-tabs and saves work.</li><li><strong><a href="./../user-guide/addons">Addons Guide →</a></strong> — per-addon usage notes and client surfaces.</li></ul>',139)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
